// Handler creates http.Handler with routing matching OpenAPI spec.
func Handler(si ServerInterface) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{})
}

// ServeMux is an abstraction of [http.ServeMux].
type ServeMux interface {
	HandleFunc(pattern string, handler func(http.ResponseWriter, *http.Request))
	http.Handler
}

type StdHTTPServerOptions struct {
	BaseURL          string
	BaseRouter       ServeMux
	Middlewares      []MiddlewareFunc
	ErrorHandlerFunc func(w http.ResponseWriter, r *http.Request, err error)
}

// HandlerFromMux creates http.Handler with routing matching OpenAPI spec based on the provided mux.
func HandlerFromMux(si ServerInterface, m ServeMux) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseRouter: m,
	})
}

func HandlerFromMuxWithBaseURL(si ServerInterface, m ServeMux, baseURL string) http.Handler {
	return HandlerWithOptions(si, StdHTTPServerOptions{
		BaseURL:    baseURL,
		BaseRouter: m,
	})
}

// HandlerWithOptions creates http.Handler with additional options
func HandlerWithOptions(si ServerInterface, options StdHTTPServerOptions) http.Handler {
	m := options.BaseRouter

	if m == nil {
		m = http.NewServeMux()
	}
	if options.ErrorHandlerFunc == nil {
		options.ErrorHandlerFunc = func(w http.ResponseWriter, r *http.Request, err error) {
			http.Error(w, err.Error(), http.StatusBadRequest)
		}
	}

	wrapper := ServerInterfaceWrapper{
		Handler:            si,
		HandlerMiddlewares: options.Middlewares,
		ErrorHandlerFunc:   options.ErrorHandlerFunc,
	}

	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/health", wrapper.GetHealth)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/locations", wrapper.GetApiLocations)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/locations", wrapper.PostApiLocations)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/locations/{id}", wrapper.DeleteApiLocationsId)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/locations/{id}", wrapper.GetApiLocationsId)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/locations/{id}", wrapper.PutApiLocationsId)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/routes", wrapper.GetApiRoutes)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/routes", wrapper.PostApiRoutes)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/routes/{id}", wrapper.DeleteApiRoutesId)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/routes/{id}", wrapper.GetApiRoutesId)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/routes/{id}", wrapper.PutApiRoutesId)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/routes/{id}/completions", wrapper.PostApiRoutesIdCompletions)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/events", wrapper.GetApiEvents)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/events", wrapper.PostApiEvents)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/events/{id}", wrapper.DeleteApiEventsId)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/events/{id}", wrapper.GetApiEventsId)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/events/{id}", wrapper.PutApiEventsId)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/events/{id}/media", wrapper.GetApiEventsIdMedia)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/events/{id}/media", wrapper.PostApiEventsIdMedia)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/events/{id}/sources", wrapper.GetApiEventsIdSources)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/events/{id}/sources/{source_id}", wrapper.DeleteApiEventsIdSourcesSourceId)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/events/{id}/sources/{source_id}", wrapper.PostApiEventsIdSourcesSourceId)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/tags", wrapper.GetApiTags)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/tags", wrapper.PostApiTags)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/tags/{id}", wrapper.DeleteApiTagsId)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/tags/{id}", wrapper.PutApiTagsId)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/sources", wrapper.GetApiSources)
	m.HandleFunc(http.MethodPost+" "+options.BaseURL+"/api/sources", wrapper.PostApiSources)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/sources/{id}", wrapper.DeleteApiSourcesId)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/sources/{id}", wrapper.GetApiSourcesId)
	m.HandleFunc(http.MethodPut+" "+options.BaseURL+"/api/sources/{id}", wrapper.PutApiSourcesId)
	m.HandleFunc(http.MethodDelete+" "+options.BaseURL+"/api/media/{id}", wrapper.DeleteApiMediaId)
	m.HandleFunc(http.MethodGet+" "+options.BaseURL+"/api/map/events.geojson", wrapper.GetApiMapEventsGeojson)

	return m
}
